import { PLAN_IDS, PLANS, TRIAL_DAYS } from "@/lib/billing/plans";
import { siteConfig } from "@/lib/site";

import type { FaqItem } from "./faq-data";

/** schema.org builders for the public site. Prices come from the plan catalogue. */

const ORG_ID = `${siteConfig.url}/#organization`;
const APP_ID = `${siteConfig.url}/#software`;

export function organizationNode() {
  return {
    "@type": "Organization",
    "@id": ORG_ID,
    name: siteConfig.name,
    alternateName: siteConfig.shortName,
    url: siteConfig.url,
    // Raster logo (180×180 PNG) generated by app/apple-icon.tsx.
    logo: `${siteConfig.url}/apple-icon`,
    slogan: siteConfig.tagline,
    description: siteConfig.description,
    email: siteConfig.supportEmail,
  };
}

export function softwareApplicationNode() {
  return {
    "@type": "SoftwareApplication",
    "@id": APP_ID,
    name: siteConfig.name,
    alternateName: siteConfig.shortName,
    url: siteConfig.url,
    description: siteConfig.description,
    applicationCategory: "BusinessApplication",
    applicationSubCategory: "AI search visibility monitoring",
    operatingSystem: "Web browser",
    publisher: { "@id": ORG_ID },
    offers: PLAN_IDS.map((id) => {
      const plan = PLANS[id];
      return {
        "@type": "Offer",
        name: `${plan.name} plan`,
        description: `${plan.tagline} ${TRIAL_DAYS}-day free trial.`,
        url: `${siteConfig.url}/pricing`,
        price: plan.monthlyPrice.toFixed(2),
        priceCurrency: "USD",
        availability: "https://schema.org/InStock",
        priceSpecification: {
          "@type": "UnitPriceSpecification",
          price: plan.monthlyPrice.toFixed(2),
          priceCurrency: "USD",
          unitCode: "MON",
          referenceQuantity: { "@type": "QuantitativeValue", value: 1, unitCode: "MON" },
        },
      };
    }),
  };
}

export function faqPageNode(items: FaqItem[], path: string) {
  return {
    "@type": "FAQPage",
    "@id": `${siteConfig.url}${path === "/" ? "" : path}/#faq`,
    mainEntity: items.map((item) => ({
      "@type": "Question",
      name: item.question,
      acceptedAnswer: { "@type": "Answer", text: item.answer },
    })),
  };
}

/** Wraps nodes in a single JSON-LD document. */
export function jsonLdGraph(...nodes: Array<Record<string, unknown>>) {
  return { "@context": "https://schema.org", "@graph": nodes };
}
